{"path":"assets/css/styles.css","content":"/* HVAC Premium Template Styles */
:root {
  --bg: #0b1020;
  --bg-elev: #0f1530;
  --panel: #121936;
  --brand: #3ec1d3;
  --brand-2: #7df9ff;
  --accent: #ffc857;
  --text: #eef2ff;
  --muted: #b7c0d6;
  --ok: #2ecc71;
  --warn: #ff8c42;
  --err: #ff5a5f;
  --border: rgba(255,255,255,0.12);
  --shadow: 0 10px 30px rgba(0,0,0,0.35);
  --radius: 14px;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Noto Sans, Ubuntu, Cantarell, Helvetica Neue, Arial, sans-serif;
  color: var(--text);
  background: radial-gradient(1200px 800px at 80% -20%, rgba(61,222,255,0.08), transparent 60%),
              linear-gradient(180deg, var(--bg) 0%, #0a0e1a 100%);
}
img { max-width: 100%; display: block; }
a { color: var(--brand-2); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { width: min(1120px, 94%); margin: 0 auto; }
.grid { display: grid; gap: 24px; }
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  padding: 14px 20px; border-radius: 12px; border: 1px solid var(--border);
  background: linear-gradient(180deg, #1a224a, #10183a);
  color: var(--text); font-weight: 600; letter-spacing: .2px;
  box-shadow: var(--shadow);
}
.btn:hover { filter: brightness(1.15); transform: translateY(-1px); transition: .2s ease; text-decoration: none; }
.btn.brand { background: linear-gradient(180deg, #39afbf, #2b7d88); border-color: rgba(61,222,255,.4); color: #061016; }
.btn.ghost { background: transparent; border-color: var(--border); }
.badge { display:inline-flex; align-items:center; gap:8px; padding:6px 10px; border-radius:999px; border:1px solid var(--border); background:rgba(255,255,255,0.04); color:var(--muted); font-size:12px; }
.tag { padding:4px 10px; border:1px solid var(--border); border-radius:999px; color:var(--muted); font-size:12px; }
.small { font-size: 14px; color: var(--muted); }
.muted { color: var(--muted); }
.h1 { font-size: clamp(34px, 4.5vw, 56px); line-height: 1.05; margin: 0 0 10px; letter-spacing: -0.02em; }
.h2 { font-size: clamp(26px, 3.5vw, 40px); line-height: 1.1; margin: 0 0 8px; letter-spacing: -0.01em; }
.h3 { font-size: clamp(20px, 2.4vw, 26px); line-height: 1.2; margin: 0 0 6px; }
.lead { font-size: clamp(16px, 2vw, 20px); color: var(--muted); }
.card {
  background: linear-gradient(180deg, #131a3a, #0e1633);
  border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow);
}
.header {
  position: sticky; top: 0; z-index: 50; backdrop-filter: blur(10px);
  background: rgba(6,12,32,0.72); border-bottom: 1px solid var(--border);
}
.navbar { display:flex; align-items:center; justify-content:space-between; padding: 14px 0; }
.brand { display:flex; align-items:center; gap:12px; text-decoration:none; }
.brand .logo {
  width: 36px; height: 36px; border-radius: 8px; background: radial-gradient(14px 14px at 70% 30%, rgba(255,255,255,.35), rgba(0,0,0,0)), linear-gradient(180deg, #38bfd0, #1b2a68);
  border: 1px solid rgba(255,255,255,0.3);
}
.brand .name { font-weight:800; letter-spacing:.3px; color: var(--text); }
nav ul { display:flex; align-items:center; gap:16px; list-style:none; padding:0; margin:0; }
nav a { color: var(--muted); padding: 10px 12px; border-radius: 8px; }
nav a[aria-current="page"], nav a:hover { color: var(--text); background: rgba(255,255,255,0.06); text-decoration:none; }
.nav-cta { display:none; }
#nav-toggle { display:none; background:transparent; border:1px solid var(--border); width:42px; height:42px; border-radius:10px; color:var(--text); }
#nav-toggle svg { width: 22px; height: 22px; }
.hero { position: relative; padding: 60px 0 30px; }
.hero .wrap { display:grid; grid-template-columns: 1.1fr .9fr; gap: 36px; align-items:center; }
.hero .visual { position: relative; }
.hero .abstract { position:absolute; inset: -12% -16% auto auto; opacity: .45; filter: drop-shadow(0 10px 40px rgba(62,193,211,.35)); }
.kpis { display:grid; grid-template-columns: repeat(4,1fr); gap: 16px; margin-top: 30px; }
.kpi { padding: 14px; border-radius: 12px; border: 1px solid var(--border); background: rgba(255,255,255,0.04); }
.kpi strong { font-size: 22px; }
.section { padding: 50px 0; }
.tiles { display:grid; grid-template-columns: repeat(3,1fr); gap: 18px; }
.tile { padding: 18px; border-radius: 14px; background: linear-gradient(180deg, #121a3b, #0d1535); border:1px solid var(--border); min-height: 180px; }
.tile .icon { width: 42px; height: 42px; display:grid; place-items:center; border-radius:10px; background: rgba(62,193,211,0.14); border:1px solid rgba(62,193,211,0.35); color:#aef; }
.tile p { color: var(--muted); }
.process { display:grid; grid-template-columns: repeat(4,1fr); gap: 12px; counter-reset: step; }
.step { position:relative; padding:18px; border-radius:12px; border:1px solid var(--border); background: rgba(255,255,255,0.04); }
.step:before { counter-increment: step; content: counter(step); position:absolute; top:-12px; left:-12px; width:34px; height:34px; border-radius:8px; background: linear-gradient(180deg, #39afbf, #2b7d88); border:1px solid rgba(61,222,255,.4); color:#061016; display:grid; place-items:center; font-weight:700; }
.review-card { display:flex; gap:14px; padding: 16px; border-radius: 12px; border:1px solid var(--border); background: rgba(255,255,255,0.04); }
.review-card img { width:48px; height:48px; border-radius:999px; background:#0a122e; border:1px solid var(--border); }
.footer { margin-top: 50px; padding: 32px 0 50px; border-top: 1px solid var(--border); background: linear-gradient(180deg, #0b1230, #0a0f24); }
.footer-grid { display:grid; grid-template-columns: 1.2fr 1fr 1fr; gap: 20px; }
.footer a { color: var(--muted); }
.footer a:hover { color: var(--text); }
.input, select, textarea { width:100%; padding:14px 12px; border-radius: 10px; border:1px solid var(--border); background: rgba(255,255,255,0.04); color:var(--text); }
label { display:block; margin-bottom:6px; color: var(--muted); font-size: 14px; }
.form-grid { display:grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.form-actions { display:flex; gap:12px; align-items:center; }
.alert { padding: 12px 14px; border-radius: 10px; border:1px solid var(--border); }
.alert.ok { background: rgba(46,204,113,0.08); border-color: rgba(46,204,113,0.5); }
.alert.warn { background: rgba(255,140,66,0.08); border-color: rgba(255,140,66,0.5); }
.alert.err { background: rgba(255,90,95,0.08); border-color: rgba(255,90,95,0.5); }
.cta-bar { position: sticky; bottom: 0; z-index: 40; padding: 12px 0; background: rgba(10,16,40,.78); backdrop-filter: blur(8px); border-top:1px solid var(--border); }
.cta-wrap { display:flex; align-items:center; justify-content: space-between; gap: 14px; }
.sr-only { position:absolute !important; left:-9999px !important; width:1px !important; height:1px !important; overflow:hidden !important; }
.table { width:100%; border-collapse: collapse; }
.table th, .table td { padding: 12px; text-align:left; border-bottom:1px solid var(--border); }
.table caption { text-align:left; padding-bottom: 8px; color: var(--muted); }
.pricing { display:grid; grid-template-columns: repeat(3,1fr); gap: 18px; }
.price-card { position:relative; overflow:hidden; }
.price-card .ribbon { position:absolute; top:10px; right:-38px; transform: rotate(35deg); background: var(--accent); color:#0a0f24; font-weight:700; padding:8px 46px; }
.check { color: var(--ok); }
.x { color: var(--err); }
.hero-min { padding: 34px 0; border-bottom:1px solid var(--border); }
.breadcrumbs { display:flex; align-items:center; gap:8px; color:var(--muted); font-size:14px; }
.breadcrumbs a { color: var(--muted); }
.stat { padding: 14px; border-radius: 12px; background: rgba(255,255,255,0.04); border:1px solid var(--border); }
.list-clean { list-style:none; padding:0; margin:0; }
.hr { height:1px; background: var(--border); border:0; margin: 18px 0; }
.embed { aspect-ratio: 16/9; border-radius: 12px; border: 1px dashed var(--border); display:grid; place-items:center; color: var(--muted); }
.note { font-size: 12px; color: var(--muted); }
/* Responsive */
@media (max-width: 980px) {
  .hero .wrap { grid-template-columns: 1fr; }
  .kpis { grid-template-columns: repeat(2,1fr); }
  .tiles { grid-template-columns: repeat(2,1fr); }
  .process { grid-template-columns: repeat(2,1fr); }
  .pricing { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .cta-wrap { flex-direction: column; align-items: stretch; }
}
@media (max-width: 760px) {
  nav ul { position: fixed; inset: 66px 0 auto 0; transform: translateY(-120%); transition: .25s ease; background: rgba(6,12,32,0.98); backdrop-filter: blur(10px); border-bottom:1px solid var(--border); padding: 16px; gap: 6px; flex-direction: column; align-items: stretch; }
  nav ul.open { transform: translateY(0); }
  .nav-cta { display:flex; }
  #nav-toggle { display:inline-grid; place-items:center; }
}
/* Focus styles */
:focus { outline: 2px solid var(--brand); outline-offset: 2px; }
.skip-link { position:absolute; left:-9999px; top:auto; width:1px; height:1px; overflow:hidden; }
.skip-link:focus { position: static; width:auto; height:auto; padding:10px; background:#fff; color:#000; border-radius:6px; }
"} 
{"path":"assets/js/main.js","content":"/* HVAC Premium Template JS */
(function(){
  'use strict';
  // Mobile nav toggle
  const navToggle = document.getElementById('nav-toggle');
  const navList = document.querySelector('nav ul');
  if (navToggle && navList) {
    navToggle.addEventListener('click', function(){
      const isOpen = navList.classList.toggle('open');
      navToggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });
  }

  // Financing calculator
  function calcPayment(){
    const amountEl = document.getElementById('finance-amount');
    const aprEl = document.getElementById('finance-apr');
    const termEl = document.getElementById('finance-term');
    const resultEl = document.getElementById('finance-result');
    if(!amountEl || !aprEl || !termEl || !resultEl) return;
    const P = parseFloat(amountEl.value || '0');
    const annual = parseFloat(aprEl.value || '0');
    const n = parseInt(termEl.value || '12', 10);
    const r = annual / 100 / 12; // monthly rate
    let m = 0;
    if (r === 0) {
      m = P / n;
    } else {
      m = P * (r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
    }
    const total = m * n;
    resultEl.innerHTML = isFinite(m) ? (
      '<div class="alert ok" role="status"><strong>Estimated monthly:</strong> $' + m.toFixed(2) +
      ' <span class="small">for ' + n + ' months at ' + annual.toFixed(2) + '% APR</span><br><span class="small">Est. total: $' + total.toFixed(2) + '</span></div>'
    ) : '<div class="alert err">Enter a valid amount, APR, and term.</div>';
  }
  ['finance-amount','finance-apr','finance-term'].forEach(id=>{
    const el = document.getElementById(id);
    if (el) el.addEventListener('input', calcPayment);
  });
  calcPayment();

  // Booking form: populate time slots for selected date
  const dateInput = document.getElementById('appt-date');
  const timeSelect = document.getElementById('appt-time');
  function buildSlotsFor(date){
    if (!timeSelect) return;
    timeSelect.innerHTML = '';
    const startHour = 8; // 8 AM
    const endHour = 17; // 5 PM
    const stepMin = 30;
    const now = new Date();
    const isToday = date && new Date(date).toDateString() === now.toDateString();
    for (let h = startHour; h <= endHour; h++) {
      for (let m = 0; m < 60; m += stepMin) {
        const slot = new Date(date || now);
        slot.setHours(h, m, 0, 0);
        if (isToday && slot < now) continue; // skip past times today
        const label = slot.toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});
        const opt = document.createElement('option');
        opt.value = label;
        opt.textContent = label;
        timeSelect.appendChild(opt);
      }
    }
    if (!timeSelect.options.length) {
      const opt = document.createElement('option');
      opt.value = '';
      opt.textContent = 'No slots available';
      timeSelect.appendChild(opt);
    }
  }
  if (dateInput) {
    const today = new Date();
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth()+1).padStart(2,'0');
    const dd = String(today.getDate()).padStart(2,'0');
    dateInput.min = `${yyyy}-${mm}-${dd}`;
    dateInput.addEventListener('change', e=> buildSlotsFor(e.target.value));
    buildSlotsFor(`${yyyy}-${mm}-${dd}`);
  }

  // Simple client-side form validation helper
  document.querySelectorAll('form[data-validate]')?.forEach(form => {
    form.addEventListener('submit', function(e){
      let ok = true;
      form.querySelectorAll('[required]')?.forEach(field => {
        if (!field.value || (field.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(field.value))) {
          ok = false;
          field.setAttribute('aria-invalid', 'true');
          field.classList.add('err');
        } else {
          field.removeAttribute('aria-invalid');
          field.classList.remove('err');
        }
      });
      if (!ok) {
        e.preventDefault();
        alert('Please complete the required fields.');
      }
    });
  });
})();
"} 
