{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{BUSINESS_NAME}} | {{TAGLINE}} | Trusted HVAC in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} delivers premium HVAC installation, repair, and maintenance in {{CITY}}, {{STATE}}. Fast response, honest pricing, and 5-star comfort. Call {{PHONE}}.">
  <meta name="robots" content="index,follow">
  <link rel="canonical" href="/index.html">
  <meta property="og:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta property="og:description" content="Premium HVAC service in {{CITY}}, {{STATE}}. Installation, repair, maintenance. Call {{PHONE}}.">
  <meta property="og:type" content="website">
  <meta property="og:url" content="/index.html">
  <meta property="og:image" content="/assets/img/hero-abstract.svg">
  <meta property="og:site_name" content="{{BUSINESS_NAME}}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta name="twitter:description" content="Premium HVAC service in {{CITY}}, {{STATE}}.">
  <meta name="twitter:image" content="/assets/img/hero-abstract.svg">
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "HVACBusiness",
    "name": "{{BUSINESS_NAME}}",
    "slogan": "{{TAGLINE}}",
    "url": "/",
    "telephone": "{{PHONE}}",
    "email": "{{EMAIL}}",
    "image": "/assets/img/hero-abstract.svg",
    "address": {
      "@type": "PostalAddress",
      "streetAddress": "{{ADDRESS}}",
      "addressLocality": "{{CITY}}",
      "addressRegion": "{{STATE}}",
      "postalCode": "{{ZIP}}"
    },
    "areaServed": "{{CITY}}, {{STATE}}",
    "openingHours": "{{HOURS}}",
    "priceRange": "$$"
  }
  </script>
  <link rel="stylesheet" href="/assets/css/styles.css">
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="header" role="banner">
    <div class="container navbar">
      <a class="brand" href="/index.html" aria-label="{{BUSINESS_NAME}} home">
        <div class="logo" aria-hidden="true"></div>
        <div class="name">{{BUSINESS_NAME}}</div>
      </a>
      <nav aria-label="Primary">
        <button id="nav-toggle" aria-controls="primary-menu" aria-expanded="false" aria-label="Toggle menu">
          <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M4 6h16v2H4zm0 5h16v2H4zm0 5h16v2H4z"/></svg>
        </button>
        <ul id="primary-menu">
          <li><a href="/services.html">Services</a></li>
          <li><a href="/pricing.html">Pricing</a></li>
          <li><a href="/financing.html">Financing</a></li>
          <li><a href="/about.html">About</a></li>
          <li><a href="/reviews.html">Reviews</a></li>
          <li class="nav-cta"><a class="btn brand" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
      <div class="hide-sm"><a class="btn brand" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
    </div>
  </header>

  <main id="main">
    <section class="hero" aria-label="Hero">
      <div class="container wrap">
        <div>
          <div class="badge" aria-label="24/7 emergency line"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2a10 10 0 100 20 10 10 0 000-20zm1 10.59l3.7 3.7-1.41 1.41L11 12.41V7h2v5.59z"/></svg> 24/7 Emergency: <strong class="small" style="margin-left:6px">{{PHONE}}</strong></div>
          <h1 class="h1">Comfort engineered. Reliability guaranteed.</h1>
          <p class="lead">We design, install, and maintain efficient heating and cooling systems for homes and businesses in {{CITY}}, {{STATE}}. Zero surprises, just peak performance and pristine air.</p>
          <div class="form-actions" style="margin-top:16px">
            <a class="btn brand" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/services.html">Explore Services</a>
          </div>
          <div class="kpis" role="group" aria-label="Key performance stats">
            <div class="kpi"><div class="small">Response</div><strong>Same‑Day</strong></div>
            <div class="kpi"><div class="small">Warranty</div><strong>Up to 12 yrs</strong></div>
            <div class="kpi"><div class="small">Savings</div><strong>30%+ Energy</strong></div>
            <div class="kpi"><div class="small">Reviews</div><strong>4.9 ★</strong></div>
          </div>
        </div>
        <div class="visual">
          <img class="abstract" src="/assets/img/hero-abstract.svg" width="560" height="380" alt="Cooling abstract">
          <div class="card" aria-label="Quick estimate">
            <h2 class="h3">Instant comfort estimate</h2>
            <p class="small">Tell us about your home to price a new system in minutes.</p>
            <form data-validate action="#" method="post" novalidate>
              <div class="form-grid">
                <div>
                  <label for="zip">ZIP</label>
                  <input id="zip" class="input" inputmode="numeric" pattern="[0-9]*" name="zip" placeholder="{{ZIP}}" required>
                </div>
                <div>
                  <label for="size">Sq Ft</label>
                  <input id="size" class="input" type="number" min="400" step="50" name="size" placeholder="2000" required>
                </div>
                <div>
                  <label for="type">System</label>
                  <select id="type" class="input" name="type">
                    <option>Heat Pump</option>
                    <option>Gas Furnace + AC</option>
                    <option>Mini‑Split</option>
                    <option>Rooftop Unit</option>
                  </select>
                </div>
                <div>
                  <label for="email">Email</label>
                  <input id="email" class="input" type="email" name="email" placeholder="you@example.com" required>
                </div>
              </div>
              <div class="form-actions" style="margin-top:12px">
                <button class="btn brand" type="submit">Get My Estimate</button>
                <span class="small">or call <a href="tel:{{PHONE}}">{{PHONE}}</a></span>
              </div>
            </form>
          </div>
        </div>
      </div>
    </section>

    <section class="section" aria-labelledby="svc-heading">
      <div class="container">
        <div style="display:flex; align-items:baseline; justify-content:space-between; gap:12px; flex-wrap:wrap;">
          <h2 class="h2" id="svc-heading">HVAC expertise without the guesswork</h2>
          <a class="tag" href="/services.html">See all services</a>
        </div>
        <div class="tiles" style="margin-top:14px">
          <article class="tile">
            <div class="icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="currentColor" width="22" height="22"><path d="M4 6h16v12H4z" opacity=".6"/><path d="M6 8h12v8H6z"/></svg></div>
            <h3 class="h3">Installation & Replacement</h3>
            <p>Right‑sized systems for maximum comfort and efficiency. We handle load calculations, permits, and clean installs.</p>
          </article>
          <article class="tile">
