{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Pricing | {{BUSINESS_NAME}} — Transparent HVAC Plans</title>
  <meta name="description" content="Clear HVAC pricing from {{BUSINESS_NAME}}. Maintenance plans and guide rails for installs and repairs in {{CITY}}, {{STATE}}.">
  <meta name="robots" content="index,follow">
  <link rel="canonical" href="/pricing.html">
  <meta property="og:title" content="Pricing | {{BUSINESS_NAME}}">
  <meta property="og:description" content="Transparent HVAC pricing and membership plans.">
  <meta property="og:type" content="website">
  <meta property="og:url" content="/pricing.html">
  <meta property="og:image" content="/assets/img/hero-abstract.svg">
  <meta property="og:site_name" content="{{BUSINESS_NAME}}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="Pricing | {{BUSINESS_NAME}}">
  <meta name="twitter:description" content="Transparent HVAC pricing and membership plans.">
  <meta name="twitter:image" content="/assets/img/hero-abstract.svg">
  <link rel="stylesheet" href="/assets/css/styles.css">
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="header"><div class="container navbar">
    <a class="brand" href="/index.html"><div class="logo"></div><div class="name">{{BUSINESS_NAME}}</div></a>
    <nav aria-label="Primary">
      <button id="nav-toggle" aria-controls="primary-menu" aria-expanded="false" aria-label="Toggle menu"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M4 6h16v2H4zm0 5h16v2H4zm0 5h16v2H4z"/></svg></button>
      <ul id="primary-menu">
        <li><a href="/services.html">Services</a></li>
        <li><a href="/pricing.html" aria-current="page">Pricing</a></li>
        <li><a href="/financing.html">Financing</a></li>
        <li><a href="/about.html">About</a></li>
        <li><a href="/reviews.html">Reviews</a></li>
        <li class="nav-cta"><a class="btn brand" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></li>
      </ul>
    </nav>
    <div class="hide-sm"><a class="btn brand" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
  </div></header>

  <main id="main">
    <section class="hero-min">
      <div class="container">
        <nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/index.html">Home</a> › <span aria-current="page">Pricing</span></nav>
        <h1 class="h1">Transparent, honest pricing</h1>
        <p class="lead">Flat‑rate repairs. Straightforward installs. No surprises—ever.</p>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <h2 class="h2">Membership plans</h2>
        <div class="pricing" style="margin-top:14px">
          <article class="card price-card">
            <h3 class="h3">Essential</h3>
            <p class="small">For newer systems that need routine care.</p>
            <div class="hr"></div>
            <p><strong>$14.95/mo</strong> per system</p>
            <ul class="small">
              <li><span class="check">✓</span> 1 seasonal tune‑up</li>
              <li><span class="check">✓</span> Priority scheduling</li>
              <li><span class="check">✓</span> 5% repair discount</li>
              <li><span class="x">✕</span> Filter program</li>
            </ul>
            <div class="form-actions" style="margin-top:10px"><a class="btn brand" href="/book.html">Choose Essential</a></div>
          </article>
          <article class="card price-card">
            <div class="ribbon" aria-hidden="true">Most Popular</div>
            <h3 class="h3">Comfort</h3>
            <p class="small">Best value for reliable year‑round comfort.</p>
            <div class="hr"></div>
            <p><strong>$24.95/mo</strong> per system</p>
            <ul class="small">
              <li><span class="check">✓</span> 2 seasonal tune‑ups</li>
              <li><span class="check">✓</span> Priority + 10% off repairs</li>
              <li><span class="check">✓</span> Filter program reminders</li>
              <li><span class="check">✓</span> $0 diagnostic with repair</li>
            </ul>
            <div class="form-actions" style="margin-top:10px"><a class="btn brand" href="/book.html">Choose Comfort</a></div>
          </article>
          <article class="card price-card">
            <h3 class="h3">Platinum</h3>
            <p class="small">Maximum protection for older or critical systems.</p>
            <div class="hr"></div>
            <p><strong>$39.95/mo</strong> per system</p>
            <ul class="small">
              <li><span class="check">✓</span> 2 seasonal tune‑ups + mid‑season check</li>
              <li><span class="check">✓</span> 15% off repairs</li>
              <li><span class="check">✓</span> Filter program included</li>
              <li><span class="check">✓</span> Annual IAQ check</li>
            </ul>
            <div class="form-actions" style="margin-top:10px"><a class="btn brand" href="/book.html">Choose Platinum</a></div>
          </article>
        </div>
        <p class="note" style="margin-top:10px">Prices shown are typical; final pricing may vary by system type and quantity. Cancel anytime.</p>
      </div>
    </section>

    <section class="section">
      <div class="container grid" style="grid-template-columns:1.1fr .9fr; align-items:start;">
        <div>
          <h2 class="h2">Installation guide rails</h2>
          <table class="table small" aria-describedby="install-desc">
            <caption id="install-desc">Typical ranges for fully installed, permits included.</caption>
            <thead><tr><th>System</th><th>Good</th><th>Better</th><th>Best</th></tr></thead>
            <tbody>
              <tr><td>Heat Pump</td><td>$7k–$10k</td><td>$10k–$14k</td><td>$14k–$20k</td></tr>
              <tr><td>Gas Furnace + AC</td><td>$6k–$9k</td><td>$9k–$13k</td><td>$13k–$18k</td></tr>
              <tr><td>Ductless Mini‑Split</td><td>$4k–$7k</td><td>$7k–$11k</td><td>$11k–$16k</td></tr>
              <tr><td>Rooftop Unit</td><td>$9k–$14k</td><td>$14k–$22k</td><td>$22k–$35k</td></tr>
            </tbody>
          </table>
          <p class="note">Exact pricing depends on home size, ductwork, electrical, and brand features. We provide firm quotes after an on‑site assessment.</p>
        </div>
        <div>
          <h2 class="h2">Repair pricing</h2>
          <ul class="small">
            <li>Diagnostic visit: <strong>$89</strong> (waived with most repairs)</li>
            <li>Capacitors/Contactors: <strong>$150–$380</strong></li>
            <li>Fan Motors: <strong>$450–$850</strong></li>
            <li>Refrigerant issues: <strong>$350–$1,200</strong></li>
            <li>Smart thermostat install: <strong>$195–$350</strong></li>
          </ul>
          <div class="card" style="margin-top:10px">
            <h3 class="h3">Financing available</h3>
            <p class="small">As low as 0% promo APR on qualifying systems. Check options in minutes—no impact to credit.</p>
            <a class="btn" href="/financing.html">View financing</a>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container card">
        <h2 class="h3">Get a firm quote</h2>
        <form data-validate action="#" method="post" class="form-grid" novalidate>
          <div><label for="name">Name</label><input id="name" class="input" name="name" required></div>
          <div><label for="p">Phone</label><input id="p" class="input" name="phone" inputmode="tel" placeholder="{{PHONE}}" required></div>
          <div><label for="zip2">ZIP</label><input id="zip2" class="input" name="zip" inputmode="numeric" pattern="[0-9]*" placeholder="{{ZIP}}" required></div>
          <div><label for="msg">Project details</label><textarea id="msg" class="input" name="message" rows="3" placeholder="Tell us about your home and comfort goals"></textarea></div>
          <div class="form-actions"><button class="btn brand" type="submit">Request Quote</button><span class="small">or call <a href="tel:{{PHONE}}">{{PHONE}}</a></span></div>
        </form>
      </div>
    </section>
  </main>

  <footer class="footer"><div class="container footer-grid">
    <div><a class="brand" href="/index.html"><div class="logo"></div><div class="name">{{BUSINESS_NAME}}</div></a><p class="small">{{TAGLINE}}</p><p class="small">Hours: {{HOURS}}</p></div>
    <div><h3 class="h3">Explore</h3><ul class="list-clean small"><li><a href="/services.html">Services</a></li><li><a href="/reviews.html">Reviews</a></li></ul></div>
